 for(let i=0;i<count;i+=3){const ds=verts.map((p,k)=>local.distanceToPoint(p.fromBufferAttribute(pos,idx?idx.getX(i+k):i+k)));if(ds.every(d=>d>=0)||ds.every(d=>d<=0))continue;const hits=[];for(let k=0;k<3;k++){const j=(k+1)%3;if((ds[k]<0)!==(ds[j]<0)){hits.push(verts[k].clone().lerp(verts[j],ds[k]/(ds[k]-ds[j])));}}if(hits.length!==2)continue;const a=get(hits[0]),b=get(hits[1]);if(a===b)continue;const key=a<b?a+':'+b:b+':'+a;if(edges.has(key))continue;edges.add(key);adj.get(a).add(b);adj.get(b).add(a);}
