 for(let y=0;y<size;y++)for(let x=0;x<size;x++){const i=y*size+x;if(x)dist[i]=Math.min(dist[i],dist[i-1]+dx);if(y)dist[i]=Math.min(dist[i],dist[i-size]+dy);if(x&&y)dist[i]=Math.min(dist[i],dist[i-size-1]+diag);if(x<size-1&&y)dist[i]=Math.min(dist[i],dist[i-size+1]+diag);}
