 let texture=null;if(tissue===1&&cut){const field=boundaryField(cut.contours,cut.bounds);texture=new THREE.DataTexture(field.pixels,field.size,field.size,THREE.RedFormat);texture.minFilter=texture.magFilter=THREE.LinearFilter;texture.needsUpdate=true;m.userData.boundaryTexture=texture;}
